// Fixed-hit, independent-temperature envelope. Does not simulate thresholds, PDE counting,
// branching fluctuations, saturation, pixel recovery, or layer-by-layer temperatures.
#include <TROOT.h>
#include <TH1D.h>
#include <TF1.h>
#include <TFitResult.h>
#include <TFitResultPtr.h>
#include <algorithm>
#include <array>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <numeric>
#include <random>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
namespace fs=std::filesystem;
using V=std::vector<double>;
void need(bool ok,const std::string&s){if(!ok)throw std::runtime_error(s);}
double mean(const V&a){return std::accumulate(a.begin(),a.end(),0.)/a.size();}
double sd(const V&a){double m=mean(a),v=0;for(double x:a)v+=(x-m)*(x-m);return std::sqrt(v/a.size());}
double cv(const V&a){return sd(a)/mean(a);}
double q(V a,double p){if(a.empty())return NAN;std::sort(a.begin(),a.end());double k=p*(a.size()-1);size_t i=k;return a[i]+(k-i)*(a[std::min(i+1,a.size()-1)]-a[i]);}
double core(const V&a){return (q(a,.84)-q(a,.16))/(2*q(a,.5));}
std::vector<std::string>split(const std::string&s){std::vector<std::string>a;std::istringstream r(s);for(std::string x;std::getline(r,x,'\t');)a.push_back(x);return a;}
struct Table {std::vector<std::string>head;std::map<std::string,int>index;std::vector<std::vector<std::string>>rows;explicit Table(const fs::path&p){std::ifstream f(p);need(bool(f),"Missing "+p.string());std::string s;std::getline(f,s);head=split(s);for(size_t i=0;i<head.size();++i)index[head[i]]=i;while(std::getline(f,s)){auto a=split(s);need(a.size()==head.size(),"Malformed table "+p.string());rows.push_back(a);}}double value(size_t row,const std::string&key)const{return std::stod(rows.at(row).at(index.at(key)));}const std::string&str(size_t row,const std::string&key)const{return rows.at(row).at(index.at(key));}};
struct D {int file,run;long long entry;double e,t,withinT;};
struct M {int file;long long entry;double e,e10,e15;};
struct Params {double alpha,u,p,beta=.06;};
const std::array<Params,2>params={Params{1.6/135.,4.5,.1},Params{3.5/230.,4.,.15}};
struct Model {std::string name;int pde;int correction;};
// correction -1=baseline; 0=raw; 1=gain-only inverse; 2=full inverse;
// 3=existing wrong-direction multiplicative gain correction; 4=gain only physics.
const std::vector<Model>models={{"CT_input_20C_baseline",0,-1},{"raw_gain_only",0,4},{"raw_gain_CT_PDEconstant",0,0},{"raw_gain_CT_PDElinear",1,0},{"gain_corrected_CT_PDEconstant",0,1},{"gain_corrected_CT_PDElinear",1,1},{"full_response_corrected_PDEconstant",0,2},{"full_response_corrected_PDElinear",1,2},{"existing_correction_direction_PDEconstant",0,3},{"existing_correction_direction_PDElinear",1,3}};
double factor(double t,int type,const Model&m){if(m.correction<0||m.correction==2)return 1;auto a=params[type];double dt=t-20,u=a.u-a.beta*dt,g=1-a.alpha*dt,p=a.p*std::pow(u/a.u,2);need(g>0&&u>0&&p<1,"Nonphysical assumed response");if(m.correction==4)return g;double f=g*(1-a.p)/(1-p)*std::pow(u/a.u,m.pde);if(m.correction==1)return f/g;if(m.correction==3)return f*g;return f;}
struct Moment {double mu=0,second=0,cv=NAN;};
Moment expected(const std::vector<M>&m,const std::vector<D>&d,const Model&model,bool within){double a=0,b=0,aa=0,bb=0,ab=0;for(const auto&x:d){double t=within?x.withinT:x.t,f0=factor(t,0,model),f1=factor(t,1,model);a+=f0;b+=f1;aa+=f0*f0;bb+=f1*f1;ab+=f0*f1;}double nd=d.size();a/=nd;b/=nd;aa/=nd;bb/=nd;ab/=nd;Moment out;for(auto x:m){out.mu+=x.e10*a+x.e15*b;out.second+=x.e10*x.e10*aa+x.e15*x.e15*bb+2*x.e10*x.e15*ab;}out.mu/=m.size();out.second/=m.size();out.cv=std::sqrt(std::max(0.,out.second/out.mu/out.mu-1));return out;}
using Blocks=std::map<int,std::map<long long,std::vector<size_t>>>;
template<class T>std::vector<T>resample(const std::vector<T>&a,std::mt19937_64&rng){Blocks blocks;for(size_t i=0;i<a.size();++i)blocks[a[i].file][a[i].entry/100].push_back(i);std::vector<T>out;for(auto&f:blocks){std::vector<std::vector<size_t>>vv;for(auto&b:f.second)vv.push_back(b.second);for(size_t j=0;j<vv.size();++j)for(size_t i:vv[std::uniform_int_distribution<size_t>(0,vv.size()-1)(rng)])out.push_back(a[i]);}return out;}
struct Fit {double value=NAN;int status=-1;};
Fit gaussian(const V&v){Fit out;double mu=mean(v),sigma=sd(v);TH1D h("temperature_estimate_hist","",240,.3*mu,1.7*mu);for(double x:v)h.Fill(x);TF1 f("temperature_estimate_gaussian","gaus",.015,10);f.SetParameters(h.GetMaximum(),mu,sigma);auto r=h.Fit(&f,"QSN","",std::max(.015,mu-3*sigma),mu+3*sigma);out.status=int(r);mu=f.GetParameter(1);sigma=std::abs(f.GetParameter(2));if(out.status||!(mu>0&&sigma>0))return out;r=h.Fit(&f,"QSN","",std::max(.015,mu-1.5*sigma),mu+1.5*sigma);out.status=int(r);if(!out.status)out.value=std::abs(f.GetParameter(2))/f.GetParameter(1);return out;}
std::ofstream table(const fs::path&p){std::ofstream f(p);need(bool(f),"Cannot write "+p.string());f<<std::setprecision(14);return f;}
int main(int argc,char**argv)try{need(argc==3,"Usage: TemperatureResolutionEstimate RESULT_BASE OUTPUT_BASE");fs::path base=argv[1],out=argv[2];fs::create_directories(out);gROOT->SetBatch();TH1::AddDirectory(false);auto summary=table(out/"summary.tsv"),temps=table(out/"temperature_distribution.tsv"),required=table(out/"required_temperature_spread.tsv"),run=table(out/"run_temperatures.tsv"),validation=table(out/"validation.tsv");
summary<<"energy_GeV\ttemperature_population\tmodel\tpilot_events\tdata_events\tdata_RMS\tCT_baseline_RMS\texact_expected_RMS\tRMS_delta_pp\tRMS_delta_q16_pp\tRMS_delta_q84_pp\tvariance_gap_reduction\tgap_q16\tgap_q84\tmean_over_CTbaseline\tmean_ratio_q16\tmean_ratio_q84\tfactor_RMS_over_mean\tsampled_core_mean\tsampled_core_q16\tsampled_core_q84\tsampled_Gaussian_mean\tsampled_Gaussian_q16\tsampled_Gaussian_q84\tGaussian_fit_successful_assignments\tfixed_mean_temperature_RMS\ttemperature_spread_only_RMS_delta_pp\tfixed_mean_relative_variance_shift\tthermal_spread_relative_variance_increment\n";
temps<<"energy_GeV\tpopulation\tevents\tmean_C\tRMS_C\tq16_C\tmedian_C\tq84_C\tmin_C\tmax_C\tCTpilot_energy_fraction_10um\n";required<<"energy_GeV\tpopulation\tmodel\teffective_log_slope_per_C\tobserved_temperature_RMS_C\tneeded_common_gain_CV\tneeded_temperature_RMS_C_linear\n";run<<"energy_GeV\trun\tevents\tmean_C\tRMS_C\n";validation<<"energy_GeV\tpilot_events\tdata_events\tmax_energy_partition_error_GeV\tfull_correction_RMS_error\n";
for(int beam:{5,20,100}){Table dt(base/"integrated/comparison/20mm"/(std::to_string(beam)+"GeV/events.tsv")),mt(base/"digitization/comparison/20mm"/(std::to_string(beam)+"GeV/paired_events.tsv"));std::vector<D>d;std::vector<M>m;V de,me,allT;std::map<int,V>byRun;double maxerror=0,e10=0,e15=0;
for(size_t i=0;i<dt.rows.size();++i)if(dt.str(i,"sample")=="data"&&dt.value(i,"cog20")&&dt.value(i,"energy_window")&&!dt.value(i,"tail_rich")){D a{int(dt.value(i,"file")),int(dt.value(i,"run")),static_cast<long long>(dt.value(i,"entry")),dt.value(i,"energy_GeV"),dt.value(i,"mean_temperature_C"),0};need(std::isfinite(a.t)&&a.t>0&&a.t<50,"Invalid event temperature");d.push_back(a);de.push_back(a.e);allT.push_back(a.t);byRun[a.run].push_back(a.t);}double tmean=mean(allT);for(auto&a:d)a.withinT=a.t-mean(byRun.at(a.run))+tmean;for(auto&[r,t]:byRun)run<<beam<<'\t'<<r<<'\t'<<t.size()<<'\t'<<mean(t)<<'\t'<<sd(t)<<'\n';
for(size_t i=0;i<mt.rows.size();++i)if(mt.value(i,"old_cog20")&&mt.value(i,"old_window")){M a{int(mt.value(i,"file")),static_cast<long long>(mt.value(i,"entry")),mt.value(i,"new_GeV"),mt.value(i,"new_10um_GeV"),mt.value(i,"new_15um_GeV")};maxerror=std::max(maxerror,std::abs(a.e-a.e10-a.e15));m.push_back(a);me.push_back(a.e);e10+=a.e10;e15+=a.e15;}need(m.size()>20&&d.size()>20&&maxerror<1e-9,"Insufficient or inconsistent selected events");double r0=cv(me),rd=cv(de),fraction=e10/(e10+e15),needed=std::sqrt(std::max(0.,(rd*rd-r0*r0)/(1+r0*r0)));std::mt19937_64 rng(20261013+beam);std::vector<std::vector<M>>bm;std::vector<std::vector<D>>bd;for(int rep=0;rep<250;++rep){bm.push_back(resample(m,rng));bd.push_back(resample(d,rng));}
for(bool within:{false,true}){V tv;for(auto x:d)tv.push_back(within?x.withinT:x.t);std::string pop=within?"within_run_centered_same_mean":"all_runs_observed_mean_hit_temperature";temps<<beam<<'\t'<<pop<<'\t'<<d.size()<<'\t'<<mean(tv)<<'\t'<<sd(tv)<<'\t'<<q(tv,.16)<<'\t'<<q(tv,.5)<<'\t'<<q(tv,.84)<<'\t'<<*std::min_element(tv.begin(),tv.end())<<'\t'<<*std::max_element(tv.begin(),tv.end())<<'\t'<<fraction<<'\n';for(auto&model:models){Moment mom=expected(m,d,model,within);D point=d.front();point.t=point.withinT=mean(tv);Moment fixed=expected(m,std::vector<D>{point},model,false);V delta,gap,rat;for(int rep=0;rep<250;++rep){Moment mr=expected(bm[rep],bd[rep],model,within),br=expected(bm[rep],bd[rep],models.front(),within);V dv;for(auto a:bd[rep])dv.push_back(a.e);double dr=cv(dv),den=dr*dr-br.cv*br.cv;delta.push_back(100*(mr.cv-br.cv));rat.push_back(mr.mu/br.mu);gap.push_back((mr.cv*mr.cv-br.cv*br.cv)/den);}V fv;for(double t:tv)fv.push_back(fraction*factor(t,0,model)+(1-fraction)*factor(t,1,model));V cores,gs;std::mt19937_64 srng(2026101300ULL+beam);for(int rep=0;rep<24;++rep){V v;for(auto x:m){double t=tv[std::uniform_int_distribution<size_t>(0,tv.size()-1)(srng)];v.push_back(x.e10*factor(t,0,model)+x.e15*factor(t,1,model));}cores.push_back(core(v));auto gf=gaussian(v);if(!gf.status&&std::isfinite(gf.value))gs.push_back(gf.value);}auto avg=[](const V&v){return v.empty()?NAN:mean(v);};summary<<beam<<'\t'<<pop<<'\t'<<model.name<<'\t'<<m.size()<<'\t'<<d.size()<<'\t'<<rd<<'\t'<<r0<<'\t'<<mom.cv<<'\t'<<100*(mom.cv-r0)<<'\t'<<q(delta,.16)<<'\t'<<q(delta,.84)<<'\t'<<(mom.cv*mom.cv-r0*r0)/(rd*rd-r0*r0)<<'\t'<<q(gap,.16)<<'\t'<<q(gap,.84)<<'\t'<<mom.mu/mean(me)<<'\t'<<q(rat,.16)<<'\t'<<q(rat,.84)<<'\t'<<cv(fv)<<'\t'<<avg(cores)<<'\t'<<q(cores,.16)<<'\t'<<q(cores,.84)<<'\t'<<avg(gs)<<'\t'<<q(gs,.16)<<'\t'<<q(gs,.84)<<'\t'<<gs.size()<<'\t'<<fixed.cv<<'\t'<<100*(mom.cv-fixed.cv)<<'\t'<<fixed.cv*fixed.cv-r0*r0<<'\t'<<mom.cv*mom.cv-fixed.cv*fixed.cv<<'\n';double eps=.0001,plus=fraction*factor(mean(tv)+eps,0,model)+(1-fraction)*factor(mean(tv)+eps,1,model),minus=fraction*factor(mean(tv)-eps,0,model)+(1-fraction)*factor(mean(tv)-eps,1,model),slope=std::abs(std::log(plus/minus)/(2*eps));required<<beam<<'\t'<<pop<<'\t'<<model.name<<'\t'<<slope<<'\t'<<sd(tv)<<'\t'<<needed<<'\t'<<(slope>0?needed/slope:NAN)<<'\n';}}
Moment full=expected(m,d,models[6],false);need(std::abs(full.cv-r0)<1e-10,"Full response correction must cancel thermal envelope exactly");validation<<beam<<'\t'<<m.size()<<'\t'<<d.size()<<'\t'<<maxerror<<'\t'<<std::abs(full.cv-r0)<<'\n';std::cout<<beam<<" GeV: T mean="<<mean(allT)<<" RMS="<<sd(allT)<<" C; CT RMS="<<100*r0<<"%, data="<<100*rd<<"%\n";}
auto method=table(out/"methodology.tsv");method<<"quantity\tdefinition\nselection\tOld MC CoG20+old energy window fixed; data same CoG20+window and LG tail veto. CT corrected MC pilot two files, original 1000 truth entries/file.\ntemperature\tObserved integrated mean_temperature_C is arithmetic mean of retained hit temperatures/event, not calibrated reference temperature or measured event sensor average. Borrowed independently of MC truth; all hit signals use same event temperature, fully coherent scenario; no individual layer temperatures available. Within-run version removes observed run mean differences but retains global mean.\nphysics_assumptions\tFixed bias; Vov(T)=U20-0.06*(T-20), U20=4.5/4.0 V for 10/15um, pCT(T)=p20*(Vov/U20)^2 with p20=0.10/0.15. CT mean multiplicity 1/(1-p), approximate dilute branching. Gain ratio=1-alpha*(T-20), alpha=1.6/135 and3.5/230; PDE constant or linear Vov bracket. These curves are assumptions, not detector fits.\ncalibration\tRaw model changes signal; gain_corrected divides by gain(T), leaving CT/PDE; full_response_corrected divides by whole modeled response and exactly cancels mean thermal variation. existing_correction_direction multiplies again by decreasing gain(T); diagnosis only, not recommended.\nexact_moments\tIndependent product-distribution moment convolution of MC energy10/energy15 and empirical event-temperature distribution; fixed detected hit list, no reselection. Mean and RMS exact for this model, not a digitizer simulation.\nmean_vs_spread\tSummary separates evaluating all events at empirical mean temperature from temperature distribution convolution; nonzero fixed-mean width shifts reflect differing10/15um energy reweighting, not random thermal broadening.\nshape\tGaussian/core are 24 reproducible random independent temperature assignments to original pilot events; mean and q16/q84 reflect assignment variation, not fit/systematic uncertainty. Gaussian two-pass240bin fit same as integrated diagnostics.\nbootstrap\t250 paired MC and data100-original-entry blocks, stratified sourcefile, exact modeled moments recomputed. Thermal distribution also block-resampled. q16/q84 are bootstrap sampling uncertainty, not model uncertainty.\nlimitations\tNo threshold changes, gain switching, saturation, pixel recovery, photon/CT fluctuations, within-layer temperature variation, or event-position/temperature covariance simulated. Common-temperature coherence is an envelope, not a demonstrated actual sensor covariance.\nreference_gain\tConverting a gain measured at24C to20C multiplies by1/(1-alpha*4), but a constant rescaling alone does not change relative resolution. Primary lightyield must not be recalculated at each temperature from MIP/gain(T).\nrequired_sigma\tLinearized temperature RMS needed to bridge data-minus-CTMC relative variance gap, using effective slope at empirical mean temperature; diagnostic of scale, not a fitted temperature fluctuation.\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}
